import json, datetime, os, uuid, yaml

# REMINDERS_ROOT / REMINDERS_TODAY exist so the tests can run this against fixtures; the
# workflow sets neither.
ROOT = os.environ.get('REMINDERS_ROOT', '.')

# Reminder sources: (path, list key, kind, date field, steps field). Keep in step with
# SOURCES in reminders_validate.py. The notify step words each kind's notification
# separately; credential notifications are unchanged.
SOURCES = [
    ('.github/credential-rotations.yml', 'credentials', 'credential', 'expires', 'rotation_steps'),
    ('.github/compliance-reviews.yml', 'reviews', 'compliance_review', 'due', 'steps'),
]
# Entry fields passed through to the notify step (anything else in the YAML is ignored).
PASSTHROUGH = ('name', 'description', 'notes', 'jira_priority', 'remind_days_before',
               'compliance_ref', 'jira_ref')

today = datetime.date.fromisoformat(os.environ['REMINDERS_TODAY']) if os.environ.get('REMINDERS_TODAY') else datetime.date.today()
due = []
configs = {}
for config_path, list_key, kind, date_field, steps_field in SOURCES:
    config_path = os.path.normpath(os.path.join(ROOT, config_path))
    if kind == 'compliance_review' and not os.path.exists(config_path):
        configs[kind] = {}  # validate allows an absent compliance file
        continue
    with open(config_path) as f:
        configs[kind] = yaml.safe_load(f) or {}


def routing(kind):
    # Each source file carries its own notification routing.
    config = configs[kind]
    return {
        'email_to': config.get('email_to', ''),
        'email_from': config.get('email_from', ''),
        'jira_project': config.get('jira_project', 'VEP'),
    }


test_name = os.environ.get('TEST_CREDENTIAL', '').strip()
if test_name:
    # Synthetic test credential — bypasses expiration check
    due.append({
        'kind': 'credential',
        'name': test_name,
        'description': f'Integration test for credential rotation notifications',
        'date': today.isoformat(),
        'days_left': 0,
        'remind_days_before': 15,
        'jira_priority': 'Lowest',
        'steps': '1. This is a test notification — no action required\n2. Close the GitHub issue and Jira ticket when done testing',
        'notes': 'Generated by workflow_dispatch with test_credential input',
        'is_test': True,
        **routing('credential'),
    })
    print(f"Test mode: sending notifications for synthetic credential '{test_name}'")
else:
    for config_path, list_key, kind, date_field, steps_field in SOURCES:
        for entry in configs[kind].get(list_key) or []:
            date = datetime.date.fromisoformat(str(entry[date_field]))
            days_left = (date - today).days
            if days_left <= entry.get('remind_days_before', 15):
                item = {k: entry[k] for k in PASSTHROUGH if k in entry}
                item.update(kind=kind, date=str(entry[date_field]), steps=str(entry[steps_field]),
                            days_left=days_left, **routing(kind))
                due.append(item)

delimiter = f"ghadelimiter_{uuid.uuid4()}"
with open(os.environ['GITHUB_OUTPUT'], 'a') as f:
    f.write(f"result<<{delimiter}\n")
    f.write(json.dumps({'due': due}))
    f.write(f"\n{delimiter}\n")
    f.write(f"has_due={'true' if due else 'false'}\n")

if due and not test_name:
    print(f"{len(due)} reminder(s) due:")
    for c in due:
        past = 'EXPIRED' if c['kind'] == 'credential' else 'OVERDUE'
        status = f"{past} ({abs(c['days_left'])} days ago)" if c['days_left'] < 0 else f"{c['days_left']} days left"
        print(f"  - [{c['kind']}] {c['name']}: {status}")
elif not due:
    print("No credentials or compliance reviews due")
